SELECT

FROM restore_record
WHERE deleted = 1

    AND source_type = #{sourceType,jdbcType=TINYINT}


    AND status = #{status,jdbcType=TINYINT}


    AND create_time >= #{startTime,jdbcType=TIMESTAMP}


    AND create_time <= #{endTime,jdbcType=TIMESTAMP}

ORDER BY create_time DESC

mapper.update:
UPDATE restore_record
SET status = #{status,jdbcType=TINYINT},
    update_time = NOW()

        , duration_ms = #{durationMs,jdbcType=BIGINT}


        , error_message = #{errorMessage,jdbcType=LONGVARCHAR}

WHERE id = #{id,jdbcType=BIGINT} AND deleted = 1
